INSERT INTO perguntas (id_quiz, id_tipo, descricao) VALUES (@q, 3, 'Avalie: Os calcogênios pertencem ao Grupo 16 da Tabela Periódica (como oxigênio e enxofre) e possuem 6 elétrons na camada de valência.');
