INSERT INTO respostas (id_pergunta, descricao, certo, ordem, texto_alvo) VALUES
(@p, 'Raio Atômico e Eletropositividade', 1, 1, 'Crescem de cima para baixo nos grupos e da direita para a esquerda nos períodos'),
