INSERT INTO perguntas (id_quiz, id_tipo, descricao) VALUES (@q, 1, 'Na "Ética a Nicômaco", como Aristóteles define a virtude moral (como a coragem)?');
INSERT INTO respostas (id_pergunta, descricao, certo, ordem) VALUES
