INSERT INTO perguntas (id_quiz, id_tipo, descricao) VALUES (@q, 3, 'Avalie: Os ecossistemas podem ser naturais (como florestas e oceanos) ou artificiais/modificados pelo ser humano (como açudes e lavouras).');
