INSERT INTO respostas (id_pergunta, descricao, certo, ordem) VALUES
(@p, 'Árvores e gramíneas (capim)', 1, 0),
(@p, 'Algas marinhas e fitoplâncton', 1, 0),
(@p, 'Musgos e samambaias', 1, 0),
(@p, 'Cogumelos e onças-pintadas', 0, 0);
