INSERT INTO perguntas (id_quiz, id_tipo, descricao) VALUES (@q, 1, 'Por que não há crase em "Refiro-me a pessoas honestas"?');
INSERT INTO respostas (id_pergunta, descricao, certo, ordem) VALUES
